/**
 * Fonts generated by tools/gen_fonts.sh <diameter> into src/fonts/<diameter>/
 * (Inter instanced at the mockup's weights + Tabler icon glyphs).
 * Build exactly one set, matching BREW_UI_DISP_SIZE.
 */
#pragma once

#include "lvgl.h"

LV_FONT_DECLARE(brew_font_num_big);   /* Inter 360 - home temperature digits    */
LV_FONT_DECLARE(brew_font_num_hist);  /* Inter 360 - history temperature digits */
LV_FONT_DECLARE(brew_font_deg_big);   /* Inter 450 - degree sign (home)         */
LV_FONT_DECLARE(brew_font_deg_hist);  /* Inter 450 - degree sign (history)      */
LV_FONT_DECLARE(brew_font_status);    /* Inter 450 - status line                */
LV_FONT_DECLARE(brew_font_small);     /* Inter 450 - secondary text             */
LV_FONT_DECLARE(brew_font_menu);      /* Inter 450 + icons - menu items         */
LV_FONT_DECLARE(brew_font_menu_bold); /* Inter 560 + icons - selected menu item */

/* Tabler icon codepoints (UTF-8) */
#define BREW_ICON_BEER      "\xEE\xBE\xA1" /* U+EFA1 */
#define BREW_ICON_SNOWFLAKE "\xEE\xB0\x8B" /* U+EC0B */
#define BREW_ICON_PAUSE     "\xEE\xB5\x85" /* U+ED45 */
#define BREW_ICON_PLAY      "\xEE\xB5\x86" /* U+ED46 */
#define BREW_ICON_CHART     "\xEE\xA9\x9C" /* U+EA5C */
#define BREW_ICON_TEMP      "\xEE\xAC\xB8" /* U+EB38 */
